param([Parameter(Mandatory=$true)][string]$ProjectId,[Parameter(Mandatory=$true)][string]$Region,[string]$WorkerPool="recovery-worker",[int]$MinAlertPolicies=2,[string[]]$RequiredPolicyPattern=@(),[string]$Operator=$env:USERNAME,[string]$ReleaseId="",[string]$OutputPath="deploy/pilot-evidence/observability_alerts.json")
$ErrorActionPreference="Stop";if($MinAlertPolicies-lt1){throw "MinAlertPolicies must be at least 1."};if(-not(Get-Command gcloud -ErrorAction SilentlyContinue)){throw "gcloud is required"};if([string]::IsNullOrWhiteSpace($Operator)){throw "Operator is required"}
$workerRaw=gcloud run worker-pools describe $WorkerPool --project $ProjectId --region $Region --format=json;if($LASTEXITCODE-ne0){throw "Could not describe Cloud Run worker pool."};$worker=$workerRaw|ConvertFrom-Json;$container=$worker.template.containers|Select-Object -First 1;if(-not$container){throw "Worker pool has no container definition."}
$startupPath=$container.startupProbe.httpGet.path;$livenessPath=$container.livenessProbe.httpGet.path;$startupPort=$container.startupProbe.httpGet.port;$livenessPort=$container.livenessProbe.httpGet.port;$healthOk=($startupPath-eq"/startup")-and($livenessPath-eq"/health")-and($startupPort-gt0)-and($livenessPort-gt0)
$policyRaw=gcloud monitoring policies list --project $ProjectId --format=json;if($LASTEXITCODE-ne0){throw "Could not list Cloud Monitoring alert policies."};$policies=@($policyRaw|ConvertFrom-Json);$enabled=@($policies|Where-Object{$_.enabled-ne$false});$names=@($enabled|ForEach-Object{[string]$_.displayName}|Where-Object{-not[string]::IsNullOrWhiteSpace($_)});$patternsMissing=@();foreach($pattern in $RequiredPolicyPattern){if([string]::IsNullOrWhiteSpace($pattern)){continue};$found=$false;foreach($name in $names){if($name-match$pattern){$found=$true;break}};if(-not$found){$patternsMissing+=$pattern}}
$alertsOk=($enabled.Count-ge$MinAlertPolicies)-and($patternsMissing.Count-eq0);$status=if($healthOk-and$alertsOk){"pass"}else{"fail"};$detail="Worker startup/liveness probes configured=$healthOk; enabled Cloud Monitoring policies=$($enabled.Count), required minimum=$MinAlertPolicies; missing required policy patterns=$($patternsMissing.Count).";$refs=@("gcloud run worker-pools describe $WorkerPool --project $ProjectId --region $Region --format=json","gcloud monitoring policies list --project $ProjectId --format=json")
$evidence=[ordered]@{schema_version="recovery-pilot-evidence.v1";kind="observability_alerts";status=$status;performed_at=(Get-Date).ToUniversalTime().ToString("o");operator=$Operator;release_id=if([string]::IsNullOrWhiteSpace($ReleaseId)){$null}else{$ReleaseId};detail=$detail;evidence_refs=$refs;metadata=[ordered]@{worker_pool=$WorkerPool;startup_probe_path=$startupPath;startup_probe_port=$startupPort;liveness_probe_path=$livenessPath;liveness_probe_port=$livenessPort;enabled_alert_policy_count=$enabled.Count;enabled_alert_policy_names=$names;required_policy_patterns=$RequiredPolicyPattern;missing_required_policy_patterns=$patternsMissing}}
$parent=Split-Path -Parent $OutputPath;if($parent-and-not(Test-Path $parent)){New-Item -ItemType Directory -Force -Path $parent|Out-Null};$evidence|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 $OutputPath;Write-Host "Wrote $OutputPath ($status)";if($status-ne"pass"){exit 2}
